package com.playtimelimit;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("play-time-limit")
public interface PlayTimeLimitConfig extends Config
{
	@Range(min = 1, max = 1440)
	@ConfigItem(
		keyName = "limitMinutes",
		name = "Daily limit (minutes)",
		description = "Total play time allowed today before alerts start"
	)
	default int limitMinutes()
	{
		return 60;
	}

	@Range(min = 1, max = 60)
	@ConfigItem(
		keyName = "reminderIntervalMinutes",
		name = "Reminder every (minutes)",
		description = "How often to repeat alerts after you go over the limit"
	)
	default int reminderIntervalMinutes()
	{
		return 1;
	}

	@ConfigItem(
		keyName = "chatWarning",
		name = "Chat warning",
		description = "Send warning messages to the game chat"
	)
	default boolean chatWarning()
	{
		return true;
	}

	@ConfigItem(
		keyName = "desktopNotification",
		name = "Desktop notification",
		description = "Show a desktop notification when over the limit"
	)
	default boolean desktopNotification()
	{
		return true;
	}

	@ConfigItem(
		keyName = "beep",
		name = "Sound alert",
		description = "Play a short system beep with each warning"
	)
	default boolean beep()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTodayTotalOnClock",
		name = "Clock shows today's total",
		description = "If enabled, the bottom clock shows your total playtime today; otherwise it shows time since login"
	)
	default boolean showTodayTotalOnClock()
	{
		return true;
	}
}

package com.playtimelimit;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

@Singleton
public class PlayTimeLimitOverlay extends Overlay
{
	private static final Color FLASH_COLOR = new Color(255, 0, 0, 110);
	private static final Color PANEL_COLOR = new Color(0, 0, 0, 215);
	private static final Color MAIN_TEXT_COLOR = new Color(255, 255, 255, 250);
	private static final Color SUB_TEXT_COLOR = new Color(255, 245, 245, 250);
	private static final String WARNING_LINE_1 = "Take a break";
	private static final String WARNING_LINE_2 = "You hit today's limit";
	private static final Color BUTTON_TIMER_BG = new Color(80, 0, 0, 230);
	private static final Color BUTTON_TIMER_TEXT = new Color(255, 220, 220, 255);
	private static final int CLOCK_RIGHT_MARGIN = 2;

	private final Client client;
	private final PlayTimeLimitPlugin plugin;

	@Inject
	private PlayTimeLimitOverlay(Client client, PlayTimeLimitPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(OverlayPriority.HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.shouldRenderClock())
		{
			return null;
		}

		renderBottomClock(graphics);

		if (!plugin.shouldFlashRed())
		{
			return null;
		}

		Color previous = graphics.getColor();
		Font previousFont = graphics.getFont();
		graphics.setColor(FLASH_COLOR);
		graphics.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());

		graphics.setFont(previousFont.deriveFont(Font.BOLD, 44f));
		FontMetrics line1Metrics = graphics.getFontMetrics();
		int line1Width = line1Metrics.stringWidth(WARNING_LINE_1);
		int line1X = (client.getCanvasWidth() - line1Width) / 2;
		int line1Y = (client.getCanvasHeight() / 2) - 18;

		graphics.setFont(previousFont.deriveFont(Font.BOLD, 30f));
		FontMetrics line2Metrics = graphics.getFontMetrics();
		int line2Width = line2Metrics.stringWidth(WARNING_LINE_2);
		int line2X = (client.getCanvasWidth() - line2Width) / 2;
		int line2Y = line1Y + 44;

		graphics.setColor(PANEL_COLOR);
		graphics.fillRoundRect(line2X - 18, line1Y - 40, Math.max(line1Width, line2Width) + 36, 98, 12, 12);

		graphics.setFont(previousFont.deriveFont(Font.BOLD, 44f));
		graphics.setColor(MAIN_TEXT_COLOR);
		graphics.drawString(WARNING_LINE_1, line1X, line1Y);

		graphics.setFont(previousFont.deriveFont(Font.BOLD, 30f));
		graphics.setColor(SUB_TEXT_COLOR);
		graphics.drawString(WARNING_LINE_2, line2X, line2Y);

		graphics.setColor(previous);
		graphics.setFont(previousFont);
		return null;
	}

	private void renderBottomClock(Graphics2D graphics)
	{
		Color previousColor = graphics.getColor();
		Font previousFont = graphics.getFont();

		String totalText = formatHms(plugin.getClockPlayedSeconds());

		graphics.setFont(previousFont.deriveFont(Font.BOLD, 14f));
		FontMetrics textMetrics = graphics.getFontMetrics();
		int textWidth = textMetrics.stringWidth(totalText);

		int panelWidth = textWidth + 20;
		int panelHeight = 20;

		Widget buttonsWidget = client.getWidget(ComponentID.CHATBOX_BUTTONS);
		Widget tradeWidget = client.getWidget(ComponentID.CHATBOX_TAB_TRADE);
		if (buttonsWidget == null || tradeWidget == null)
		{
			graphics.setColor(previousColor);
			graphics.setFont(previousFont);
			return;
		}

		Rectangle buttonRowBounds = buttonsWidget.getBounds();
		Rectangle tradeBounds = tradeWidget.getBounds();
		int x = buttonRowBounds.x + buttonRowBounds.width - panelWidth - CLOCK_RIGHT_MARGIN;
		int y = tradeBounds.y + Math.max(0, (tradeBounds.height - panelHeight) / 2);

		graphics.setColor(BUTTON_TIMER_BG);
		graphics.fillRoundRect(x, y, panelWidth, panelHeight, 6, 6);

		graphics.setColor(BUTTON_TIMER_TEXT);
		graphics.drawString(totalText, x + (panelWidth - textWidth) / 2, y + 15);

		graphics.setColor(previousColor);
		graphics.setFont(previousFont);
	}

	private static String formatHms(long totalSeconds)
	{
		long safeSeconds = Math.max(0L, totalSeconds);
		long hours = TimeUnit.SECONDS.toHours(safeSeconds);
		long minutes = TimeUnit.SECONDS.toMinutes(safeSeconds) % 60;
		long seconds = safeSeconds % 60;
		return String.format("%02d:%02d:%02d", hours, minutes, seconds);
	}
}

package com.playtimelimit;

import com.google.inject.Provides;
import java.awt.Toolkit;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.temporal.ChronoUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.task.Schedule;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Play Time Limit",
	description = "Tracks daily playtime and reminds you to take a break after you hit your limit",
	tags = {"time", "limit", "break", "session"}
)
public class PlayTimeLimitPlugin extends Plugin
{
	private static final String BUILD_MARKER = "PTL_LOCAL_TOTAL_1_1_4";
	private static final String STATE_GROUP = "play-time-limit-state";
	private static final String STATE_DAY_KEY = "trackedDay";
	private static final String STATE_SECONDS_KEY = "dailyPlayedSeconds";
	private static final String STATE_TOTAL_SECONDS_KEY = "totalPlayedSeconds";
	private static final int MIN_PERSIST_INTERVAL_SECONDS = 10;
	private static final String FIRST_WARNING_PREFIX = "Limit reached";
	private static final String REMINDER_WARNING_PREFIX = "Still over limit";

	@Inject
	private Client client;

	@Inject
	private Notifier notifier;

	@Inject
	private PlayTimeLimitConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PlayTimeLimitOverlay overlay;

	private LocalDate trackedDay;
	private long dailyPlayedSeconds;
	private long totalPlayedSeconds;
	private long sessionPlayedSeconds;
	private long unsavedSeconds;
	private Instant lastAccrualTick;
	private Instant lastWarning;
	private boolean limitExceeded;
	private boolean flashOn;

	@Override
	protected void startUp()
	{
		log.debug("Play Time Limit started");
		log.info("Play Time Limit build marker: {}", BUILD_MARKER);
		configManager.setConfiguration(STATE_GROUP, "buildMarker", BUILD_MARKER);
		overlayManager.add(overlay);
		loadState();
		ensureToday();
	}

	@Override
	protected void shutDown()
	{
		log.debug("Play Time Limit stopped");
		overlayManager.remove(overlay);
		persistState(true);
		resetRuntimeState();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (gameState == GameState.LOGGED_IN)
		{
			if (lastAccrualTick == null)
			{
				sessionPlayedSeconds = 0;
			}
			lastAccrualTick = Instant.now();
			ensureToday();
		}

		if (gameState == GameState.LOGIN_SCREEN)
		{
			lastAccrualTick = null;
			flashOn = false;
			limitExceeded = false;
			persistState(true);
		}
	}

	@Schedule(period = 1, unit = ChronoUnit.SECONDS)
	public void checkPlayLimit()
	{
		ensureToday();

		if (!isLoggedIn())
		{
			return;
		}

		Instant now = Instant.now();
		if (lastAccrualTick == null)
		{
			lastAccrualTick = now;
			return;
		}

		long elapsedSeconds = Duration.between(lastAccrualTick, now).getSeconds();
		if (elapsedSeconds > 0)
		{
			dailyPlayedSeconds += elapsedSeconds;
			totalPlayedSeconds += elapsedSeconds;
			sessionPlayedSeconds += elapsedSeconds;
			unsavedSeconds += elapsedSeconds;
			lastAccrualTick = now;
			persistState(false);
		}

		long limitSeconds = Math.max(1, config.limitMinutes()) * 60L;
		limitExceeded = dailyPlayedSeconds >= limitSeconds;
		if (!limitExceeded)
		{
			flashOn = false;
			return;
		}

		long playedMinutes = dailyPlayedSeconds / 60;
		int limitMinutes = config.limitMinutes();
		if (lastWarning == null)
		{
			sendWarning(playedMinutes, limitMinutes, true);
			return;
		}

		long secondsFromLastWarning = Duration.between(lastWarning, now).getSeconds();
		long reminderIntervalSeconds = Math.max(1, config.reminderIntervalMinutes()) * 60L;

		if (secondsFromLastWarning >= reminderIntervalSeconds)
		{
			sendWarning(playedMinutes, limitMinutes, false);
		}
	}

	@Schedule(period = 500, unit = ChronoUnit.MILLIS)
	public void updateFlash()
	{
		if (!isLoggedIn() || !limitExceeded)
		{
			flashOn = false;
			return;
		}

		flashOn = !flashOn;
	}

	private void sendWarning(long playedMinutes, int limitMinutes, boolean firstWarning)
	{
		String prefix = firstWarning ? FIRST_WARNING_PREFIX : REMINDER_WARNING_PREFIX;
		String message = String.format("%s: played %d min today (limit %d min). Time for a break.", prefix, playedMinutes, limitMinutes);

		if (config.chatWarning())
		{
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
		}

		if (config.desktopNotification())
		{
			notifier.notify(message);
		}

		if (config.beep())
		{
			Toolkit.getDefaultToolkit().beep();
		}

		lastWarning = Instant.now();
		log.debug("Play limit warning sent: {}", message);
	}

	private boolean isLoggedIn()
	{
		return client.getGameState() == GameState.LOGGED_IN;
	}

	boolean shouldFlashRed()
	{
		return flashOn && limitExceeded && isLoggedIn();
	}

	private void resetRuntimeState()
	{
		lastAccrualTick = null;
		lastWarning = null;
		limitExceeded = false;
		sessionPlayedSeconds = 0;
		flashOn = false;
	}

	private void ensureToday()
	{
		LocalDate today = currentDay();
		if (trackedDay == null)
		{
			trackedDay = today;
			persistState(true);
			return;
		}

		if (!today.equals(trackedDay))
		{
			trackedDay = today;
			dailyPlayedSeconds = 0;
			unsavedSeconds = 0;
			lastWarning = null;
			limitExceeded = false;
			flashOn = false;
			persistState(true);
		}
	}

	private void loadState()
	{
		String dayValue = configManager.getConfiguration(STATE_GROUP, STATE_DAY_KEY);
		if (dayValue != null && !dayValue.isEmpty())
		{
			try
			{
				trackedDay = LocalDate.parse(dayValue);
			}
			catch (RuntimeException ex)
			{
				log.debug("Invalid stored day '{}', resetting state", dayValue, ex);
			}
		}

		String secondsValue = configManager.getConfiguration(STATE_GROUP, STATE_SECONDS_KEY);
		if (secondsValue != null && !secondsValue.isEmpty())
		{
			try
			{
				dailyPlayedSeconds = Math.max(0L, Long.parseLong(secondsValue));
			}
			catch (NumberFormatException ex)
			{
				log.debug("Invalid stored seconds '{}', resetting to 0", secondsValue, ex);
				dailyPlayedSeconds = 0L;
			}
		}

		String totalSecondsValue = configManager.getConfiguration(STATE_GROUP, STATE_TOTAL_SECONDS_KEY);
		if (totalSecondsValue != null && !totalSecondsValue.isEmpty())
		{
			try
			{
				totalPlayedSeconds = Math.max(0L, Long.parseLong(totalSecondsValue));
			}
			catch (NumberFormatException ex)
			{
				log.debug("Invalid stored total seconds '{}', resetting to 0", totalSecondsValue, ex);
				totalPlayedSeconds = 0L;
			}
		}

		long limitSeconds = Math.max(1, config.limitMinutes()) * 60L;
		limitExceeded = dailyPlayedSeconds >= limitSeconds;
	}

	private void persistState(boolean force)
	{
		if (!force && unsavedSeconds < MIN_PERSIST_INTERVAL_SECONDS)
		{
			return;
		}

		if (trackedDay != null)
		{
			configManager.setConfiguration(STATE_GROUP, STATE_DAY_KEY, trackedDay.toString());
		}
		configManager.setConfiguration(STATE_GROUP, STATE_SECONDS_KEY, Long.toString(dailyPlayedSeconds));
		configManager.setConfiguration(STATE_GROUP, STATE_TOTAL_SECONDS_KEY, Long.toString(totalPlayedSeconds));
		unsavedSeconds = 0;
	}

	long getTotalPlayedSeconds()
	{
		return totalPlayedSeconds;
	}

	long getDailyPlayedSeconds()
	{
		return dailyPlayedSeconds;
	}

	long getSessionPlayedSeconds()
	{
		return sessionPlayedSeconds;
	}

	long getClockPlayedSeconds()
	{
		return config.showTodayTotalOnClock() ? dailyPlayedSeconds : sessionPlayedSeconds;
	}

	int getDailyLimitMinutes()
	{
		return config.limitMinutes();
	}

	boolean shouldRenderClock()
	{
		return isLoggedIn();
	}

	private LocalDate currentDay()
	{
		return LocalDate.now(ZoneId.systemDefault());
	}

	@Provides
	PlayTimeLimitConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PlayTimeLimitConfig.class);
	}
}

package com.playtimelimit;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class PlayTimeLimitPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(PlayTimeLimitPlugin.class);
		RuneLite.main(args);
	}
}
